SELECT ROUND(SUM(CASE WHEN element = 'cl' THEN 1 ELSE 0 END) * 1.0 / COUNT(*), 4) AS chlorine_percentage
FROM atom
WHERE molecule_id IN (SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '-');

SELECT COUNT(DISTINCT bond_id) AS bonds_with_hydrogen
FROM bond
WHERE molecule_id = 'TR499'
AND bond_id IN (
  SELECT bond_id FROM connected WHERE atom_id IN (
    SELECT atom_id FROM atom WHERE element = 'h' AND molecule_id = 'TR499'
  )
);
